class Solution {
public:
    string shortestBeautifulSubstring(string s, int k) {
        vector<int> ones;
        for (int i = 0; i < s.size(); i++) if (s[i] == '1') ones.push_back(i);
        if (ones.size() < k) return "";
        string ans = "";
        int min_len = 1e9;
        for (int i = 0; i + k - 1 < ones.size(); i++) {
            int start = ones[i], end = ones[i + k - 1];
            string sub = s.substr(start, end - start + 1);
            if (sub.size() < min_len) {
                min_len = sub.size();
                ans = sub;
            } else if (sub.size() == min_len && (ans == "" || sub < ans)) {
                ans = sub;
            }
        }
        return ans;
    }
};

class Solution {
    public String shortestBeautifulSubstring(String s, int k) {
        List<Integer> ones = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) if (s.charAt(i) == '1') ones.add(i);
        if (ones.size() < k) return "";
        String ans = "";
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i + k - 1 < ones.size(); i++) {
            int start = ones.get(i), end = ones.get(i + k - 1);
            String sub = s.substring(start, end + 1);
            if (sub.length() < minLen) {
                minLen = sub.length();
                ans = sub;
            } else if (sub.length() == minLen && (ans.isEmpty() || sub.compareTo(ans) < 0)) {
                ans = sub;
            }
        }
        return ans;
    }
}

/**
 * @param {string} s
 * @param {number} k
