var shortestBeautifulSubstring = function(s, k) {
    const ones = [];
    for (let i = 0; i < s.length; i++) if (s[i] === '1') ones.push(i);
    if (ones.length < k) return '';
    let ans = '';
    let minLen = Infinity;
    for (let i = 0; i + k - 1 < ones.length; i++) {
        const start = ones[i], end = ones[i + k - 1];
        const sub = s.slice(start, end + 1);
        if (sub.length < minLen) {
            minLen = sub.length;
            ans = sub;
        } else if (sub.length === minLen && (ans === '' || sub < ans)) {
            ans = sub;
        }
    }
    return ans;
};
